    @Override
    public BigDecimal calcular(BigDecimal subtotal, List<ItemCarrinho> itens) {
        BigDecimal desconto = BigDecimal.ZERO;
        Map<String, Integer> quantidadePorItem = new HashMap<>();

        for (ItemCarrinho item : itens) {
            quantidadePorItem.merge(item.getNome(), item.getQuantidade(), Integer::sum);
        }

        for (ItemCarrinho item : itens) {
            int totalQuantidade = quantidadePorItem.get(item.getNome());
            int unidadeGratis = totalQuantidade / 3;
            desconto = desconto.add(item.getPrecoUnitario().multiply(new BigDecimal(unidadeGratis)));
        }

        return desconto;
    }

    @Override
    public boolean ehFretegratis() {
        return false;
    }

    @Override
    public List<ItemCarrinho> aplicarLeve3Pague2(List<ItemCarrinho> itens) {
        return itens;
    }
}

