public class debug {
    public static void main(String[] args) {
        // Exemplo 2
        BigDecimal total = new BigDecimal("431.45");  // 409.70 + 15.60 + 6.15
        int parcelas = 6;
        BigDecimal taxa = new BigDecimal("0.0199");

        // Formula Price: parcela = total × taxa ÷ (1 − (1 + taxa)^−número de parcelas)
        BigDecimal um = BigDecimal.ONE;
