2	
3	import com.loja.dto.CheckoutRequest;
4	import com.loja.dto.CheckoutResponse;
5	import com.loja.dto.ItemRequest;
6	import com.loja.model.FormaPagamento;
7	import com.loja.model.ItemCarrinho;
8	import com.loja.model.ModalidadeEntrega;
9	import com.loja.model.NivelClube;
10	import com.loja.model.Regiao;
11	import com.loja.model.cupom.CalculadoraDesconto;
12	import com.loja.model.cupom.CupomRegistry;
13	import com.loja.service.estrategia.AjustePagamento;
14	import com.loja.service.estrategia.AjusteBoletoPagamento;
15	import com.loja.service.estrategia.AjusteCartaoPagamento;
16	import com.loja.service.estrategia.AjustePixPagamento;
17	
18	import java.math.BigDecimal;
19	import java.util.List;
20	import java.util.stream.Collectors;
21	
22	public class CalculadoraCheckout {
23	    public CheckoutResponse calcular(CheckoutRequest request) {
24	        List<ItemCarrinho> itens = converterItens(request.getItens());
25	        ModalidadeEntrega modalidadeEntrega = ModalidadeEntrega.valueOf(request.getModalidadeEntrega());
26	        NivelClube nivelClube = NivelClube.valueOf(request.getNivelClube());
27	        Regiao regiao = Regiao.valueOf(request.getRegiao());
28	        FormaPagamento formaPagamento = FormaPagamento.valueOf(request.getFormaPagamento());
29	
30	        BigDecimal subtotalProdutos = calcularSubtotal(itens);
31	        subtotalProdutos = Arredondador.arredondar(subtotalProdutos);
32	
33	        BigDecimal descontoCupom = calcularDescontoCupom(request.getCupom(), subtotalProdutos, itens);
34	        descontoCupom = Arredondador.arredondar(descontoCupom);
35	
36	        BigDecimal frete = calcularFrete(modalidadeEntrega, itens, nivelClube, request.getCupom());
37	        frete = Arredondador.arredondar(frete);
38	
39	        BigDecimal seguro = calcularSeguro(subtotalProdutos, regiao);
40	        seguro = Arredondador.arredondar(seguro);
41	
42	        BigDecimal totalPedido = subtotalProdutos
43	                .subtract(descontoCupom)
44	                .add(frete)
45	                .add(seguro);
46	
47	        int parcelas = obterParcelas(request.getParcelas(), formaPagamento);
48	        AjustePagamento ajustadorPagamento = obterAjustadorPagamento(formaPagamento);
49	        BigDecimal ajustePagamento = ajustadorPagamento.calcularAjuste(totalPedido, parcelas);
50	        ajustePagamento = Arredondador.arredondar(ajustePagamento);
51	
52	        BigDecimal totalFinal = totalPedido.add(ajustePagamento);
53	        totalFinal = Arredondador.arredondar(totalFinal);
54	
55	        BigDecimal valorParcela = calcularValorParcela(totalFinal, parcelas);
56	        valorParcela = Arredondador.arredondar(valorParcela);
57	
58	        BigDecimal creditoProximaCompra = calcularCredito(nivelClube, subtotalProdutos);
59	        creditoProximaCompra = Arredondador.arredondar(creditoProximaCompra);
60	
61	        boolean brinde = deveBrinde(nivelClube, subtotalProdutos);
62	
63	        CheckoutResponse response = new CheckoutResponse();
64	        response.setSubtotalProdutos(subtotalProdutos);
65	        response.setDescontoCupom(descontoCupom);
66	        response.setFrete(frete);
67	        response.setPrazoEntregaDias(modalidadeEntrega.getPrazo());
68	        response.setSeguro(seguro);
69	        response.setAjustePagamento(ajustePagamento);
70	        response.setTotalFinal(totalFinal);
71	        response.setParcelas(parcelas);
72	        response.setValorParcela(valorParcela);
73	        response.setCreditoProximaCompra(creditoProximaCompra);
74	        response.setBrinde(brinde);
75	
76	        return response;
77	    }
78	
79	    private List<ItemCarrinho> converterItens(List<ItemRequest> itens) {
80	        return itens.stream()
81	                .map(i -> new ItemCarrinho(i.getNome(), i.getPrecoUnitario(), i.getQuantidade(), i.getPesoKg()))
82	                .collect(Collectors.toList());
83	    }
84	
85	    private BigDecimal calcularSubtotal(List<ItemCarrinho> itens) {
86	        return itens.stream()
87	                .map(ItemCarrinho::getSubtotal)
88	                .reduce(BigDecimal.ZERO, BigDecimal::add);
89	    }
90	
91	    private BigDecimal calcularDescontoCupom(String cupom, BigDecimal subtotal, List<ItemCarrinho> itens) {
92	        if (cupom == null || cupom.isEmpty()) {
93	            return BigDecimal.ZERO;
94	        }
95	
96	        CalculadoraDesconto calculadora = CupomRegistry.obter(cupom).orElse(null);
97	        if (calculadora == null) {
98	            return BigDecimal.ZERO;
99	        }
100	
101	        return calculadora.calcular(subtotal, itens);
102	    }
103	
104	    private BigDecimal calcularFrete(ModalidadeEntrega modalidade, List<ItemCarrinho> itens,
105	                                     NivelClube nivelClube, String cupom) {
106	        if (nivelClube.isOuro()) {
107	            return BigDecimal.ZERO;
108	        }
109	
110	        if (cupom != null && !cupom.isEmpty()) {
111	            CalculadoraDesconto calculadora = CupomRegistry.obter(cupom).orElse(null);
112	            if (calculadora != null && calculadora.ehFretegratis()) {
113	                return BigDecimal.ZERO;
114	            }
115	        }
116	
117	        BigDecimal pesoTotal = itens.stream()
118	                .map(ItemCarrinho::getPesoTotal)
119	                .reduce(BigDecimal.ZERO, BigDecimal::add);
120	
121	        return modalidade.calculateCost(pesoTotal);
122	    }
123	
124	    private BigDecimal calcularSeguro(BigDecimal subtotal, Regiao regiao) {
125	        return subtotal.multiply(regiao.getSeguroPercent());
126	    }
127	
128	    private int obterParcelas(Integer parcelasRequest, FormaPagamento formaPagamento) {
129	        AjustePagamento ajustador = obterAjustadorPagamento(formaPagamento);
130	        return ajustador.obterParcelas(parcelasRequest);
131	    }
132	
133	    private AjustePagamento obterAjustadorPagamento(FormaPagamento formaPagamento) {
134	        return switch (formaPagamento) {
135	            case PIX -> new AjustePixPagamento();
136	            case BOLETO -> new AjusteBoletoPagamento();
137	            case CARTAO -> new AjusteCartaoPagamento();
138	        };
139	    }
140	
141	    private BigDecimal calcularValorParcela(BigDecimal totalFinal, int parcelas) {
142	        return totalFinal.divide(new BigDecimal(parcelas), 2, java.math.RoundingMode.HALF_EVEN);
143	    }
144	
145	    private BigDecimal calcularCredito(NivelClube nivelClube, BigDecimal subtotal) {
146	        if (!nivelClube.isMemberWithCredit()) {
147	            return BigDecimal.ZERO;
148	        }
149	
150	        return subtotal.multiply(nivelClube.getCreditoPercent());
151	    }
152	
153	    private boolean deveBrinde(NivelClube nivelClube, BigDecimal subtotal) {
154	        if (!nivelClube.isOuro()) {
155	            return false;
156	        }
157	
158	        return subtotal.compareTo(new BigDecimal("500.00")) > 0;
159	    }
160	}
