15	    public Optional<String> validar(CheckoutRequest request) {
16	        if (pedidoInvalido(request)) {
17	            return Optional.of("PEDIDO_INVALIDO");
18	        }
19	
20	        if (nivelInvalido(request.getNivelClube())) {
21	            return Optional.of("NIVEL_CLUBE_INVALIDO");
22	        }
23	
24	        if (regiaoInvalida(request.getRegiao())) {
25	            return Optional.of("REGIAO_INVALIDA");
26	        }
27	
28	        if (modalidadeInvalida(request.getModalidadeEntrega())) {
29	            return Optional.of("MODALIDADE_INVALIDA");
30	        }
31	
32	        if (modalidadeIndisponivel(request)) {
33	            return Optional.of("MODALIDADE_INDISPONIVEL");
34	        }
35	
36	        if (cupomInvalido(request.getCupom())) {
37	            return Optional.of("CUPOM_INVALIDO");
38	        }
39	
40	        if (cupomNaoAplicavel(request)) {
41	            return Optional.of("CUPOM_NAO_APLICAVEL");
