43	
44	        if (formaPagamentoInvalida(request.getFormaPagamento())) {
45	            return Optional.of("FORMA_PAGAMENTO_INVALIDA");
46	        }
47	
48	        if (parcelamentoInvalido(request)) {
49	            return Optional.of("PARCELAMENTO_INVALIDO");
50	        }
51	
52	        if (formaPagamentoIndisponivel(request)) {
53	            return Optional.of("FORMA_PAGAMENTO_INDISPONIVEL");
54	        }
55	
56	        return Optional.empty();
57	    }
