59	    private boolean pedidoInvalido(CheckoutRequest request) {
60	        if (request.getItens() == null || request.getItens().isEmpty()) {
61	            return true;
62	        }
63	
64	        for (ItemRequest item : request.getItens()) {
65	            if (item.getNome() == null || item.getNome().isEmpty()) return true;
66	            if (item.getPrecoUnitario() == null || item.getPrecoUnitario().compareTo(BigDecimal.ZERO) <= 0) return true;
67	            if (item.getQuantidade() <= 0) return true;
68	            if (item.getPesoKg() == null || item.getPesoKg().compareTo(BigDecimal.ZERO) < 0) return true;
69	        }
70	
71	        return false;
72	    }
73	
74	    private boolean nivelInvalido(String nivel) {
75	        if (nivel == null || nivel.isEmpty()) {
76	            return true;
77	        }
78	        try {
79	            NivelClube.valueOf(nivel);
80	            return false;
81	        } catch (IllegalArgumentException e) {
82	            return true;
83	        }
84	    }
