110	    private boolean modalidadeIndisponivel(CheckoutRequest request) {
111	        ModalidadeEntrega modalidade = ModalidadeEntrega.valueOf(request.getModalidadeEntrega());
112	
113	        if (modalidade.isMototoy()) {
114	            BigDecimal pesoTotal = request.getItens().stream()
115	                    .map(item -> item.getPesoKg().multiply(new BigDecimal(item.getQuantidade())))
116	                    .reduce(BigDecimal.ZERO, BigDecimal::add);
117	
118	            return pesoTotal.compareTo(new BigDecimal("5")) > 0;
119	        }
120	
121	        return false;
122	    }
