131	    private boolean cupomNaoAplicavel(CheckoutRequest request) {
132	        if (request.getCupom() == null || request.getCupom().isEmpty()) {
133	            return false;
134	        }
135	
136	        BigDecimal subtotal = request.getItens().stream()
137	                .map(item -> item.getPrecoUnitario().multiply(new BigDecimal(item.getQuantidade())))
138	                .reduce(BigDecimal.ZERO, BigDecimal::add);
139	
140	        return !CupomRegistry.podeAplicar(request.getCupom(), subtotal);
141	    }
