143	    private boolean formaPagamentoInvalida(String formaPagamento) {
144	        if (formaPagamento == null || formaPagamento.isEmpty()) {
145	            return true;
146	        }
147	        try {
148	            FormaPagamento.valueOf(formaPagamento);
149	            return false;
150	        } catch (IllegalArgumentException e) {
151	            return true;
152	        }
153	    }
154	
155	    private boolean parcelamentoInvalido(CheckoutRequest request) {
156	        int parcelas = request.getParcelas() != null ? request.getParcelas() : 1;
157	        FormaPagamento forma = FormaPagamento.valueOf(request.getFormaPagamento());
158	
159	        if (forma == FormaPagamento.PIX || forma == FormaPagamento.BOLETO) {
160	            return parcelas != 1;
161	        }
162	
163	        if (forma == FormaPagamento.CARTAO) {
164	            return parcelas < 1 || parcelas > 12;
165	        }
166	
167	        return false;
168	    }
