170	    private boolean formaPagamentoIndisponivel(CheckoutRequest request) {
171	        FormaPagamento forma = FormaPagamento.valueOf(request.getFormaPagamento());
172	
173	        if (forma == FormaPagamento.BOLETO) {
174	            BigDecimal subtotal = request.getItens().stream()
175	                    .map(item -> item.getPrecoUnitario().multiply(new BigDecimal(item.getQuantidade())))
176	                    .reduce(BigDecimal.ZERO, BigDecimal::add);
177	
178	            return subtotal.compareTo(new BigDecimal("1000.00")) > 0;
179	        }
180	
181	        return false;
182	    }
183	}
