2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	public class AjusteCartaoPagamento implements AjustePagamento {
7	    private static final BigDecimal TAXA_JUROS = new BigDecimal("0.0199");
8	
9	    @Override
10	    public BigDecimal calcularAjuste(BigDecimal total, int parcelas) {
11	        if (parcelas <= 3) {
12	            return BigDecimal.ZERO;
13	        }
14	
15	        BigDecimal parcelaComJuros = calcularParcelaPrice(total, parcelas);
16	        BigDecimal totalComJuros = parcelaComJuros.multiply(new BigDecimal(parcelas));
17	        return totalComJuros.subtract(total);
18	    }
19	
20	    @Override
21	    public int obterParcelas(Integer parcelasRequest) {
22	        return parcelasRequest != null ? parcelasRequest : 1;
23	    }
24	
25	    private BigDecimal calcularParcelaPrice(BigDecimal total, int parcelas) {
26	        BigDecimal taxa = TAXA_JUROS;
27	        BigDecimal um = BigDecimal.ONE;
28	        BigDecimal umMaisTaxa = um.add(taxa);
29	
30	        BigDecimal potencia = umMaisTaxa.pow(parcelas);
31	        BigDecimal numerador = total.multiply(taxa).multiply(potencia);
32	        BigDecimal denominador = potencia.subtract(um);
33	
34	        return numerador.divide(denominador, 2, RoundingMode.HALF_EVEN);
35	    }
36	}
